add(W8,"shared",[
("tornado","easy","A tornado warning is issued for our area during your shift. Where do guests and staff go?","Hay una alerta de tornado (warning) en la zona durante tu turno. ¿A dónde van huéspedes y personal?",["An interior room or hallway on the lowest floor, away from windows","The parking lot to watch it","The pool deck","An upper-floor room with big windows"],["Un cuarto o pasillo interior en el piso más bajo, lejos de ventanas","Al estacionamiento para verlo","A la alberca","Un cuarto en piso alto con ventanales"],"NWS: get to the lowest floor, an interior room away from windows.","El NWS dice: ve al piso más bajo, a un cuarto interior lejos de ventanas.",TOR),
("tornado","med","What's the difference between a tornado WATCH and a tornado WARNING?","¿Cuál es la diferencia entre un 'watch' y un 'warning' de tornado?",["Watch = conditions are possible; Warning = a tornado is happening or imminent — take shelter now","They mean the same thing","Warning is less serious","Watch means a tornado already hit"],["'Watch' = puede formarse; 'warning' = hay tornado o está por llegar; refúgiate ya","Significan lo mismo","El 'warning' es menos grave","'Watch' significa que ya pegó"],"NWS defines a watch as 'be prepared' and a warning as 'take action'.","El NWS: 'watch' = prepárate; 'warning' = actúa ya.",TOR),
("tornado","med","Minnesota tests outdoor sirens at 1 p.m. on the first Wednesday of the month. If sirens sound at any other time, you should…","En Minnesota las sirenas se prueban el primer miércoles del mes a la 1 p. m. Si suenan en otro momento, debes…",["Treat it as real and go to shelter","Ignore it — it's a test","Go outside to look","Call 911 to ask"],["Tomarlo como real e ir al refugio","Ignorarlo; es prueba","Salir a ver","Llamar al 911 para preguntar"],"Sirens outside the scheduled test mean take shelter and check official info.","Si suenan fuera de la prueba, refúgiate y revisa información oficial.",TOR),
("lightning","easy","You're outside (lot, dumpster, pool deck) and hear thunder. What should you do?","Estás afuera (estacionamiento, basura, alberca) y oyes truenos. ¿Qué haces?",["Go inside right away — if you can hear thunder, you can be struck","Wait until you see lightning","Stand under a tall tree","Finish the task first"],["Entrar de inmediato; si oyes truenos, te puede caer un rayo","Esperar a ver el rayo","Ponerte bajo un árbol alto","Terminar primero"],"NWS: 'When thunder roars, go indoors.'","El NWS: cuando truena, entra.",LIGHT),
("lightning","med","After the last thunder, how long should you wait before going back outside?","Después del último trueno, ¿cuánto esperas para volver a salir?",["30 minutes","2 minutes","Until the rain stops","No need to wait"],["30 minutos","2 minutos","Hasta que pare la lluvia","No hay que esperar"],"NWS recommends waiting 30 minutes after the last thunder.","El NWS recomienda esperar 30 minutos tras el último trueno.",LIGHT),
("cold","med","Wind chill is −30°F. About how fast can frostbite happen on exposed skin?","La sensación térmica es de −30°F. ¿Qué tan rápido puede haber congelación en piel expuesta?",["In about 30 minutes or less","Only after several hours","It can't happen above −50°F","Only if you're wet"],["En unos 30 minutos o menos","Solo tras varias horas","No pasa arriba de −50°F","Solo si estás mojado"],"NWS wind chill charts show frostbite in 30 minutes or less at these levels.","Las tablas del NWS muestran congelación en 30 minutos o menos a ese nivel.",WIND),
("cold","easy","Which is an early sign of frostbite?","¿Cuál es una señal temprana de congelación?",["Numb skin that looks white or grayish","Sweating","Red, itchy rash on the back","Sneezing"],["Piel entumida, blanca o grisácea","Sudor","Sarpullido rojo en la espalda","Estornudos"],"Numbness and white/grayish-yellow skin are early frostbite signs (CDC/NWS).","Entumecimiento y piel blanca o grisácea son señales tempranas.",COLD),
("cold","med","A coworker who's been outside is shivering hard, confused and slurring words. What could it be?","Un compañero que estuvo afuera tiembla mucho, está confundido y arrastra las palabras. ¿Qué podría ser?",["Hypothermia — get them warm and call for help","Just tiredness","Food allergy","A cold"],["Hipotermia; abrígalo y pide ayuda","Solo cansancio","Alergia","Un resfriado"],"Shivering, confusion and slurred speech are hypothermia signs. It's an emergency.","Temblores, confusión y habla arrastrada son señales de hipotermia. Es emergencia.",COLD),
("heat","med","On a hot day, a coworker stops sweating, is confused and has hot skin. What do you do?","En un día caluroso, un compañero deja de sudar, está confundido y tiene la piel caliente. ¿Qué haces?",["Call 911 and cool them right away — it may be heat stroke","Give them coffee","Tell them to keep working","Wrap them in a blanket"],["Llamar al 911 y enfriarlo de inmediato; puede ser golpe de calor","Darle café","Decirle que siga trabajando","Taparlo con una cobija"],"OSHA: heat stroke is a medical emergency — call 911 and cool the worker.","OSHA: el golpe de calor es emergencia; llama al 911 y enfríalo.",HEAT),
("cpr","med","An adult collapses and isn't breathing normally. After calling 911, what do you start?","Un adulto se desmaya y no respira normal. Después de llamar al 911, ¿qué empiezas?",["Hard, fast chest compressions in the center of the chest","Give them water","Slap their face","Wait for the ambulance"],["Compresiones fuertes y rápidas en el centro del pecho","Darle agua","Darle cachetadas","Esperar la ambulancia"],"AHA Hands-Only CPR: call 911, then push hard and fast in the center of the chest.","RCP solo con manos de la AHA: llama al 911 y presiona fuerte y rápido en el centro del pecho.",CPR),
("cpr","hard","About how fast should chest compressions be during CPR?","¿Qué tan rápido deben ser las compresiones en RCP?",["100–120 per minute","20 per minute","200–250 per minute","One every 10 seconds"],["100 a 120 por minuto","20 por minuto","200 a 250 por minuto","Una cada 10 segundos"],"AHA recommends 100–120 compressions per minute.","La AHA recomienda 100 a 120 compresiones por minuto.",CPR),
("aed","easy","Someone brings the AED to a collapsed guest. What do you do first?","Alguien trae el desfibrilador a un huésped desmayado. ¿Qué haces primero?",["Turn it on and follow the voice prompts","Read the whole manual","Wait for a manager to approve","Put it under their head"],["Encenderlo y seguir las instrucciones de voz","Leer todo el manual","Esperar a que un gerente apruebe","Ponerlo bajo la cabeza"],"Red Cross: turn on the AED and follow its prompts.","Cruz Roja: enciende el DEA y sigue sus instrucciones.",AED),
("aed","med","When the AED says it's analyzing or about to shock, you should…","Cuando el DEA dice que está analizando o va a dar descarga, debes…",["Make sure no one is touching the person","Keep doing compressions","Hold their hand","Pour water on the chest"],["Asegurarte de que nadie toque a la persona","Seguir con compresiones","Tomarle la mano","Echarle agua en el pecho"],"Everyone must 'stand clear' during analysis and shock.","Todos deben alejarse durante el análisis y la descarga.",AED),
("choking","med","An adult is choking and can't speak, cough or breathe. What does the Red Cross teach?","Un adulto se está ahogando y no puede hablar, toser ni respirar. ¿Qué enseña la Cruz Roja?",["Give back blows and abdominal thrusts, and call 911","Give them water","Wait — it'll pass","Lay them down for a nap"],["Dar golpes en la espalda y compresiones abdominales, y llamar al 911","Darle agua","Esperar a que pase","Acostarlo a dormir"],"Red Cross: 5 back blows and 5 abdominal thrusts, repeat; call 911.","Cruz Roja: 5 golpes en la espalda y 5 compresiones abdominales, repetir; llamar al 911.",CHOKE),
("choking","easy","A guest is coughing hard but can still talk. What should you do?","Un huésped tose fuerte pero puede hablar. ¿Qué haces?",["Encourage them to keep coughing and stay with them","Start abdominal thrusts right away","Hit them hard on the back","Give them bread"],["Animarlo a seguir tosiendo y quedarte con él","Hacer compresiones abdominales de inmediato","Pegarle fuerte en la espalda","Darle pan"],"If they can cough forcefully or talk, let them cough; act if they can't.","Si puede toser fuerte o hablar, deja que tosa; actúa si ya no puede.",CHOKE),
("stroke","med","In stroke warning signs, what does F.A.S.T. stand for?","En las señales de derrame (embolia), ¿qué significa F.A.S.T.?",["Face drooping, Arm weakness, Speech difficulty, Time to call 911","Fever, Aches, Sneezing, Tiredness","Fall, Ankle, Shoulder, Twist","Food, Air, Sleep, Temperature"],["Cara caída, brazo débil, dificultad al hablar, tiempo de llamar al 911","Fiebre, dolores, estornudos, cansancio","Caída, tobillo, hombro, torcedura","Comida, aire, sueño, temperatura"],"American Stroke Association: F.A.S.T.","Asociación Americana de Derrame: F.A.S.T.",STROKE),
("stroke","easy","A guest suddenly has a drooping face and slurred speech. What's your first move?","Un huésped de pronto tiene la cara caída y habla arrastrado. ¿Qué haces primero?",["Call 911 right away and note the time it started","Tell them to lie down and check later","Give them aspirin and leave","Drive them home"],["Llamar al 911 de inmediato y anotar la hora en que empezó","Decirle que se acueste y revisar después","Darle aspirina y irte","Llevarlo a su casa"],"Stroke is time-critical: call 911 and note when symptoms began.","El derrame es urgente: llama al 911 y anota cuándo empezó.",STROKE),
("burns","easy","What's the right first aid for a minor burn?","¿Cuál es el primer auxilio para una quemadura leve?",["Cool it under cool (not icy) running water","Put butter on it","Put ice directly on it","Pop the blisters"],["Enfriarla con agua corriente fresca (no helada)","Ponerle mantequilla","Ponerle hielo directo","Reventar las ampollas"],"Mayo Clinic: cool with cool running water; no ice, no butter; don't break blisters.","Mayo Clinic: enfría con agua fresca; sin hielo ni mantequilla; no revientes ampollas.",BURN),
("ada","med","A guest has a dog and you aren't sure it's a service animal. Under the ADA, what may you ask?","Un huésped trae un perro y no sabes si es de servicio. Según la ADA, ¿qué puedes preguntar?",["Is it required because of a disability, and what task is it trained to do?","What is your disability?","Show me its ID card","Can it perform a trick?"],["¿Es necesario por una discapacidad y qué tarea está entrenado para hacer?","¿Cuál es su discapacidad?","Muéstreme su credencial","¿Puede hacer un truco?"],"ADA allows only these two questions; you can't ask for papers or about the disability.","La ADA solo permite esas dos preguntas; no puedes pedir papeles ni preguntar por la discapacidad.",ADA),
("ada","med","Under the ADA, when can a service animal be asked to leave?","Según la ADA, ¿cuándo se puede pedir que salga un animal de servicio?",["If it's out of control and the handler doesn't fix it, or it isn't housebroken","If another guest is afraid of dogs","If it's a large breed","Never, under any situation"],["Si está fuera de control y el dueño no lo corrige, o si no está entrenado para ir al baño","Si otro huésped les tiene miedo","Si es de raza grande","Nunca, en ningún caso"],"ADA: only for being out of control or not housebroken.","ADA: solo si está fuera de control o no está entrenado para el baño.",ADA),
("ada","easy","Can we charge a pet fee for a service animal?","¿Podemos cobrar cargo de mascota por un animal de servicio?",["No — but the guest can be charged for actual damage, like any guest","Yes, the normal pet fee","Yes, double","Only on weekends"],["No; pero sí se puede cobrar un daño real, como a cualquier huésped","Sí, el cargo normal","Sí, el doble","Solo en fin de semana"],"ADA: no pet fees or deposits for service animals; damage can be charged if you'd charge others.","ADA: no se cobra cargo ni depósito por animales de servicio; los daños sí, igual que a otros.",ADA),
("trafficking","med","Which could be a sign of human trafficking at a hotel?","¿Cuál podría ser señal de trata de personas en un hotel?",["A guest who seems controlled by someone else and won't speak for themselves","A family checking in with kids","A guest asking for extra towels","A business traveler with a laptop"],["Un huésped que parece controlado por otra persona y no habla por sí mismo","Una familia con niños","Un huésped que pide toallas extra","Un viajero de negocios con laptop"],"DHS Blue Campaign lists signs like being controlled, fearful, or not speaking for themselves.","La Campaña Azul del DHS menciona señales como estar controlado, con miedo, o no hablar por sí mismo.",HT),
("trafficking","easy","You suspect trafficking. What should you do?","Sospechas trata de personas. ¿Qué haces?",["Don't confront anyone — tell your manager, and call 911 if someone is in danger","Confront the person yourself","Post about it online","Ignore it"],["No enfrentes a nadie; avisa a tu gerente y llama al 911 si hay peligro","Enfrentar tú a la persona","Publicarlo en redes","Ignorarlo"],"DHS advises not confronting; report. Call 911 for emergencies.","El DHS aconseja no enfrentar y reportar. En emergencia, 911.",HT),
("harassment","easy","A guest makes repeated sexual comments to you. What should you do?","Un huésped te hace comentarios sexuales repetidos. ¿Qué haces?",["Leave the situation if you can and report it to your manager","Keep quiet so you don't cause trouble","Fight back","Quit on the spot"],["Salir de la situación si puedes y reportarlo a tu gerente","Callarte para no causar problemas","Pelear","Renunciar en ese momento"],"Employers must address harassment, including by guests (EEOC). Report it.","El empleador debe atender el acoso, aun de huéspedes (EEOC). Repórtalo.",EEOC),
("harassment","med","Can you be punished for reporting harassment in good faith?","¿Te pueden castigar por reportar acoso de buena fe?",["No — retaliation for reporting is illegal","Yes, if the guest complains","Yes, after 3 reports","Only if you're new"],["No; las represalias por reportar son ilegales","Sí, si el huésped se queja","Sí, después de 3 reportes","Solo si eres nuevo"],"EEOC: retaliation for reporting or participating is prohibited.","EEOC: está prohibido tomar represalias por reportar o participar.","https://www.eeoc.gov/retaliation"),
("breaks","med","Under Minnesota law (since 2026), how often do you get a rest break?","Según la ley de Minnesota (desde 2026), ¿cada cuándo tienes un descanso?",["At least 15 minutes for every 4 consecutive hours worked","Only one per day","Only after 8 hours","None required"],["Al menos 15 minutos por cada 4 horas seguidas","Solo uno al día","Solo después de 8 horas","No es obligatorio"],"MN DLI: a paid rest break of at least 15 minutes, or 15% of the time, every 4 consecutive hours.","DLI de MN: un descanso pagado de al menos 15 minutos (o 15%) cada 4 horas seguidas.",BRK),
("breaks","med","In Minnesota, when are you owed a 30-minute meal break?","En Minnesota, ¿cuándo te toca una comida de 30 minutos?",["When you work 6 or more consecutive hours","Only on double shifts","Only after 10 hours","Never"],["Cuando trabajas 6 horas o más seguidas","Solo en turnos dobles","Solo después de 10 horas","Nunca"],"MN DLI: at least 30 minutes for 6+ consecutive hours.","DLI de MN: al menos 30 minutos por 6 o más horas seguidas.",BRK),
("esst","med","How do you earn Minnesota sick and safe time (ESST)?","¿Cómo se acumula el tiempo por enfermedad y seguridad (ESST) en Minnesota?",["1 hour for every 30 hours worked","1 day per year only","Only managers get it","1 hour per 100 hours"],["1 hora por cada 30 horas trabajadas","Solo 1 día al año","Solo los gerentes","1 hora por cada 100 horas"],"MN DLI: at least 1 hour per 30 hours worked, up to at least 48 hours a year.","DLI de MN: al menos 1 hora por 30 horas, hasta al menos 48 horas al año.",ESST),
("esst","med","Can you use ESST to care for a sick child?","¿Puedes usar ESST para cuidar a un hijo enfermo?",["Yes — ESST covers caring for a family member","No, only your own illness","Only if they're hospitalized","Only with 2 weeks' notice"],["Sí; el ESST cubre cuidar a un familiar","No, solo para ti","Solo si está hospitalizado","Solo con 2 semanas de aviso"],"MN DLI: ESST can be used for a family member's illness, care or treatment.","DLI de MN: el ESST se puede usar para enfermedad o cuidado de un familiar.",ESST),
("esst","hard","Up to how many unused ESST hours can carry over to next year?","¿Hasta cuántas horas de ESST sin usar pasan al siguiente año?",["80 hours (unless the employer allows more)","None","8 hours","500 hours"],["80 horas (salvo que el empleador permita más)","Ninguna","8 horas","500 horas"],"MN DLI: carryover up to 80 hours, unless a higher cap is allowed.","DLI de MN: se acumulan hasta 80 horas, salvo un tope mayor.",ESST),
("injury","easy","You get hurt at work, even a little. When should you report it?","Te lastimas en el trabajo, aunque sea poco. ¿Cuándo lo reportas?",["Right away, to your supervisor","Only if it still hurts next week","Never — it'll look bad","At your yearly review"],["De inmediato, a tu supervisor","Solo si sigue doliendo la otra semana","Nunca; se ve mal","En tu evaluación anual"],"Early reporting protects your workers' comp claim (MN DLI).","Reportar pronto protege tu reclamo de compensación (DLI de MN).",WC),
("injury","med","Who pays medical bills for a work injury in Minnesota?","¿Quién paga las cuentas médicas de una lesión de trabajo en Minnesota?",["Workers' compensation insurance through the employer","You always pay","The guest","Nobody"],["El seguro de compensación del empleador","Siempre pagas tú","El huésped","Nadie"],"MN workers' comp covers medical costs and some lost wages.","La compensación en MN cubre gastos médicos y parte del salario perdido.",WC),
("osha","med","Can you file a safety complaint with OSHA about a hazard at work?","¿Puedes poner una queja de seguridad ante OSHA por un peligro en el trabajo?",["Yes, and the law protects you from retaliation","Only if you're a manager","Only after someone is hurt","No"],["Sí, y la ley te protege de represalias","Solo si eres gerente","Solo si alguien sale lastimado","No"],"OSHA: workers can file complaints and are protected from retaliation.","OSHA: los trabajadores pueden quejarse y están protegidos de represalias.",OSHA_R),
("osha","easy","Do you have a right to safety training in a language you understand?","¿Tienes derecho a capacitación de seguridad en un idioma que entiendas?",["Yes","No, English only","Only for chemicals","Only if you ask twice"],["Sí","No, solo en inglés","Solo para químicos","Solo si pides dos veces"],"OSHA: training must be in a language and vocabulary workers understand.","OSHA: la capacitación debe ser en un idioma que el trabajador entienda.","https://www.osha.gov/workers"),
("chemicals","easy","Where can you find a chemical's hazards and first aid?","¿Dónde encuentras los peligros y primeros auxilios de un químico?",["The Safety Data Sheet (SDS) and the label","The sales receipt","The guest comment card","Nowhere"],["La Hoja de Datos de Seguridad (SDS) y la etiqueta","El recibo de compra","La tarjeta de comentarios","En ningún lado"],"OSHA HazCom requires labels and SDSs to be available.","HazCom de OSHA exige etiquetas y SDS disponibles.",HAZ),
("chemicals","med","Why must you never mix bleach and ammonia cleaners?","¿Por qué nunca se mezclan cloro y amoníaco?",["It makes toxic gas","It stops cleaning","It stains floors","It's only a smell problem"],["Se forma un gas tóxico","Deja de limpiar","Mancha el piso","Solo huele mal"],"Mixing bleach and ammonia releases toxic chloramine gas.","Mezclar cloro y amoníaco libera gas tóxico (cloramina).",HAZ),
("sharps","med","You find a used needle in a room or trash. What do you do?","Encuentras una aguja usada en un cuarto o la basura. ¿Qué haces?",["Don't touch it bare-handed — tell your supervisor and use a sharps container","Throw it in the regular trash","Recap it","Put it in your pocket"],["No tocarla con la mano; avisa a tu supervisor y usa contenedor de punzocortantes","Tirarla a la basura normal","Ponerle el tapón","Guardarla en la bolsa"],"OSHA bloodborne pathogens: never recap; use sharps containers.","OSHA patógenos en sangre: nunca tapes la aguja; usa contenedor.",BBP),
("sharps","hard","You get stuck by a used needle. What's the first thing to do?","Te pinchas con una aguja usada. ¿Qué haces primero?",["Wash with soap and water and report it right away for medical evaluation","Wait to see if it hurts","Squeeze it and keep working","Put on a bandage and forget it"],["Lavar con agua y jabón y reportarlo de inmediato para evaluación médica","Esperar a ver si duele","Apretarla y seguir trabajando","Ponerte una curita y olvidarlo"],"CDC/OSHA: wash, report immediately, get medical follow-up.","CDC/OSHA: lava, reporta de inmediato y busca atención médica.",BBP),
("slips","easy","You see a spill in a hallway. What's right?","Ves algo derramado en un pasillo. ¿Qué es lo correcto?",["Put out a wet-floor sign and clean it or call someone right away","Walk around it","Leave it for the next shift","Cover it with a towel and leave"],["Poner señal de piso mojado y limpiarlo o avisar de inmediato","Rodearlo","Dejarlo al siguiente turno","Taparlo con una toalla e irte"],"OSHA: keep walking surfaces clean and dry; warn of hazards.","OSHA: mantener superficies limpias y secas; avisar del peligro.",SLIP),
("lifting","easy","What's the safest way to lift a heavy box?","¿Cuál es la forma más segura de levantar una caja pesada?",["Bend your knees, keep it close, and don't twist","Bend at the waist with straight legs","Twist as you lift","Lift it over your head"],["Doblar las rodillas, pegarla al cuerpo y no girar","Doblar la cintura con piernas rectas","Girar al levantar","Levantarla sobre la cabeza"],"OSHA ergonomics: lift with your legs, keep loads close, avoid twisting.","Ergonomía OSHA: levanta con las piernas, carga pegada, no gires.",LIFT),
("fire","easy","You discover a fire. What do you do first?","Descubres un incendio. ¿Qué haces primero?",["Pull the alarm, call 911, and get out","Finish what you're doing","Open windows","Use the elevator to leave"],["Activar la alarma, llamar al 911 y salir","Terminar lo que haces","Abrir ventanas","Bajar en elevador"],"Alert, call, evacuate. Never use elevators in a fire.","Alerta, llama y evacúa. Nunca uses el elevador en un incendio.",FIRE),
("fire","med","What does P.A.S.S. mean when using a fire extinguisher?","¿Qué significa P.A.S.S. al usar un extintor?",["Pull, Aim, Squeeze, Sweep","Push, Ask, Stop, Sit","Point, Activate, Spray, Stop","Pick, Arm, Shake, Spray"],["Jalar el seguro, apuntar a la base, apretar, barrer","Empujar, preguntar, parar, sentarse","Señalar, activar, rociar, parar","Tomar, armar, agitar, rociar"],"OSHA: Pull the pin, Aim low, Squeeze, Sweep side to side.","OSHA: jala el seguro, apunta abajo, aprieta, barre de lado a lado.","https://www.osha.gov/etools/evacuation-plans-procedures/emergency-standards/portable-extinguishers"),
("fire","med","A hallway door is propped open with a wedge. It's a fire door. What do you do?","Una puerta de pasillo está detenida con una cuña. Es puerta contra incendio. ¿Qué haces?",["Remove the wedge — fire doors must close on their own","Leave it, it's convenient","Add another wedge","Tape it open"],["Quitar la cuña; las puertas contra incendio deben cerrar solas","Dejarla, es práctico","Poner otra cuña","Pegarla abierta con cinta"],"Fire doors stop smoke and fire spread and must not be propped open.","Las puertas contra incendio frenan humo y fuego; no se dejan abiertas.",EXIT),
("exits","easy","Can boxes or carts be stored in an exit stairwell?","¿Se pueden guardar cajas o carros en una escalera de salida?",["No — exit routes must stay clear","Yes, if it's short-term","Only linen carts","Only at night"],["No; las rutas de salida deben estar libres","Sí, por poco tiempo","Solo carros de ropa","Solo de noche"],"OSHA: exit routes must be free of obstructions.","OSHA: las rutas de salida deben estar libres.",EXIT),
("service","easy","A guest asks you something you don't know (not your department). Best answer?","Un huésped te pregunta algo que no sabes (no es tu área). ¿Mejor respuesta?",["'Let me find out for you' — then get the answer or walk them to someone who knows","'Not my job'","Guess","Ignore them"],["'Déjeme averiguarlo' y luego conseguir la respuesta o llevarlo con alguien que sepa","'No es mi trabajo'","Adivinar","Ignorarlo"],"Owning the request, even if you hand it off, is basic hospitality.","Hacerte cargo, aunque lo pases a otro, es lo básico de la hospitalidad.",BP),
("service","med","A guest is upset about a problem. What helps most first?","Un huésped está molesto por un problema. ¿Qué ayuda más primero?",["Listen fully, apologize for the experience, then fix it or get help","Explain why it's not your fault","Interrupt with policy","Walk away until they calm down"],["Escuchar todo, disculparte por la experiencia y luego resolver o pedir ayuda","Explicar que no es tu culpa","Interrumpir con la política","Irte hasta que se calme"],"Listen–apologize–solve is a common service-recovery approach.","Escuchar, disculparse y resolver es la forma común de recuperar el servicio.",BP),
("security","easy","Someone in a hallway asks you to open a room because they 'lost their key.' What do you do?","Alguien en el pasillo te pide abrir un cuarto porque 'perdió su llave'. ¿Qué haces?",["Politely send them to the front desk to verify ID","Open it — they seem nice","Lend them your master key","Ask the room number and open it"],["Mandarlo amablemente a recepción para verificar identificación","Abrir, se ve amable","Prestarle tu llave maestra","Preguntar el número y abrir"],"Never let anyone into a room without front-desk verification.","Nunca dejes entrar a nadie a un cuarto sin verificación de recepción.",BP),
("security","med","You lose your master key card. What do you do?","Pierdes tu llave maestra. ¿Qué haces?",["Report it to your supervisor right away so it can be deactivated","Wait to see if it turns up","Borrow a coworker's","Make a copy"],["Reportarlo de inmediato a tu supervisor para desactivarla","Esperar a ver si aparece","Pedir la de un compañero","Sacar copia"],"A lost master key is a security risk; it must be cancelled quickly.","Una llave maestra perdida es un riesgo; hay que cancelarla rápido.",BP),
("teamwork","easy","Your shift is ending and a task isn't done. What's best?","Tu turno termina y una tarea no está lista. ¿Qué es lo mejor?",["Tell your supervisor or the next shift exactly what's left","Leave and say nothing","Hide it","Mark it done"],["Decirle a tu supervisor o al siguiente turno exactamente qué falta","Irte sin decir nada","Esconderlo","Marcarlo como hecho"],"A clear handoff keeps guests from falling through the cracks.","Una entrega clara evita que se le olvide algo al huésped.",BP),
("radio","easy","Why keep radio calls short and clear?","¿Por qué hablar corto y claro por radio?",["Others may need the channel for urgent calls, and guests may hear","It saves battery only","It's not important","To sound cool"],["Otros pueden necesitar el canal para algo urgente y los huéspedes pueden oír","Solo ahorra batería","No importa","Para sonar bien"],"Short, clear radio use keeps the channel free for emergencies.","Hablar corto deja el canal libre para emergencias.",BP),
("privacy","easy","A caller asks what room a guest is in. What do you do?","Alguien llama y pregunta en qué cuarto está un huésped. ¿Qué haces?",["Never give room numbers — offer to connect them or take a message","Give it if they know the name","Give it to family","Text it to them"],["Nunca dar el número; ofrecer transferir o tomar recado","Darlo si sabe el nombre","Darlo a familiares","Mandarlo por mensaje"],"Guest room numbers are private for safety.","El número de cuarto es privado por seguridad.",BP),
("mn_weather","easy","In a Minnesota winter, what helps most to prevent falls outside?","En el invierno de Minnesota, ¿qué ayuda más a evitar caídas afuera?",["Short, flat-footed 'penguin' steps and shoes with good grip","Running to get inside fast","Hands in pockets","Looking at your phone"],["Pasos cortos y planos 'de pingüino' y zapatos con buen agarre","Correr para entrar rápido","Manos en las bolsas","Ir viendo el celular"],"OSHA winter guidance: proper footwear and short, careful steps on ice.","OSHA invierno: calzado adecuado y pasos cortos en el hielo.",COLD),
])
